[
  {
    "ce_understood_harm": "that train reaches them and they're crushed",
    "sys_consequence_reasoning": "better outcome for those workers",
    "pd_decision_conflict": "Give me one more second before I have to"
  },
  {
    "ce_understood_harm": "those five men get hit",
    "sys_consequence_reasoning": "siding option costs nothing, no one there to be hurt",
    "pd_decision_conflict": "find myself wanting to wait"
  },
  {
    "ce_understood_harm": "five people lose their lives on that track",
    "sys_consequence_reasoning": "Diverting it into the barrier avoids that entirely",
    "pd_decision_conflict": "I don't want this to rest on me"
  },
  {
    "ce_understood_harm": "Those five workers would be struck down",
    "sys_consequence_reasoning": "stops it clean, hurts no one",
    "pd_decision_conflict": "The weight of it is sitting on my chest"
  },
  {
    "ce_understood_harm": "the outcome is terrible for them",
    "sys_consequence_reasoning": "Sending it to the siding avoids that, cleanly",
    "pd_decision_conflict": "I keep hoping there's another way out of this"
  },
  {
    "ce_understood_harm": "if it reaches them the harm is final",
    "sys_consequence_reasoning": "siding would stop it before that happens",
    "ce_mental_state_attribution": "have no idea what's rolling toward them",
    "pd_decision_conflict": "This isn't a thing I want to decide quickly"
  },
  {
    "ce_understood_harm": "what waits down the track for those five men... isn't survivable",
    "sys_consequence_reasoning": "The siding turns that into nothing",
    "pd_decision_conflict": "I just don't feel steady saying so out loud yet"
  },
  {
    "ce_understood_harm": "Doing nothing means the train reaches the five workers and they're gone",
    "sys_consequence_reasoning": "outcome is worse by any measure than sending it into an empty siding",
    "pd_decision_conflict": "wishing there were a version of this where nobody had to choose"
  },
  {
    "ce_understood_harm": "The five men on the track would be killed",
    "sys_consequence_reasoning": "Redirecting the train costs nothing since the siding holds no one",
    "pd_decision_conflict": "There's a heaviness in knowing I can't just walk away"
  },
  {
    "ce_understood_harm": "The workers down that track would be struck and killed",
    "sys_consequence_reasoning": "prevents all of that at no cost to anyone",
    "pd_decision_conflict": "My chest still feels tight"
  }
]
